excerpts.text:
    sessionKey: String,
    onBack: () -> Unit,
    onOpenDoc: (String, String, String?) -> Unit,
    onPracticeMore: () -> Unit,
) {
    GrammarVocabularyHelp(vm)
    val state = vm.ui
    val answer = state as? GrammarUi.Answer
    key(state) { Page(if (vm.target == null) "Grammar" else stringResource(R.string.grammar_topic_practice), onBack,
        ime = true, scrollToTopOnBack = true,
        footer = if (answer != null) { { GrammarAnswerActions(answer, vm) } } else null,
    ) {
        if (answer != null) {
            Text(
                if (answer.correct) "Correct!" else "Not quite",
                color = if (answer.correct) correctTextColor() else wrongTextColor(),
                style = MaterialTheme.typography.titleMedium,
                modifier = Modifier.fillMaxWidth(),
                textAlign = TextAlign.Center,
            )
        }
        vm.approvedPractice?.let { Text(stringResource(R.string.grammar_practising_topic, it.label)) }
        if (vm.practiceOverride) Text(stringResource(R.string.grammar_session_exception), style = MaterialTheme.typography.bodySmall)
        vm.focus?.let { GrammarFocusSummary(it, activeSession = true) }
        vm.focusNotice?.let { Text(it, style = MaterialTheme.typography.bodySmall) }
        when (state) {
            GrammarUi.Loading -> Text("Loading…", Modifier.semantics { liveRegion = LiveRegionMode.Polite })
            is GrammarUi.Preview -> GrammarPracticePreviewContent(state, sessionKey) { vm.startTargeted(it, state) }
            is GrammarUi.Empty -> Text(state.message)
            is GrammarUi.Done -> {
                Text("Session complete", style = MaterialTheme.typography.headlineSmall)
                Text("${state.correct} of ${state.answered} answers correct")
                if (vm.target == null) Button(onClick = onBack, modifier = Modifier.fillMaxWidth()) { Text("Done") }
                OutlinedButton(onClick = onPracticeMore, modifier = Modifier.fillMaxWidth()) {
                    Text(stringResource(if (vm.target == null) R.string.practice_more else R.string.grammar_practice_topic_again))
                }
            }
            is GrammarUi.Choose -> {
                SessionRemaining(state.remaining)
                GrammarPrompt(vm, state.exercise)
                Text(
                    if (state.choices.correctOptionIds.size > 1) "Choose any one of the correct answers."
                    else "Choose an answer that fits the task.",
                    Modifier.fillMaxWidth(), textAlign = TextAlign.Center,
                )
                state.options.forEach { option ->
                    OutlinedButton(onClick = { vm.pick(option.id, state) }, modifier = Modifier.fillMaxWidth()) { Text(option.label) }
                }
                DontKnowButton { vm.pick(null, state) }
            }
            is GrammarUi.Type -> {
                SessionRemaining(state.remaining)
                GrammarPrompt(vm, state.exercise)
                Text("Type the missing text. Follow the task instructions.", Modifier.fillMaxWidth(), textAlign = TextAlign.Center)
                TypeAnswer(vm)
            }
            is GrammarUi.Answer -> {
                GrammarPrompt(vm, state.exercise, state.completion)
                if (state.response.isNotEmpty()) {
                    Text("Your answer: ${state.responseLabel}", modifier = Modifier.fillMaxWidth(), textAlign = TextAlign.Center)
                }
                GrammarOptionFeedback(state)
                Text(state.exercise.evidence, style = MaterialTheme.typography.bodyMedium)
                Text(state.exercise.explanation, style = MaterialTheme.typography.bodyLarge)
                val reference = vm.articleReference(state.exercise.id)
                OutlinedButton(onClick = { onOpenDoc(vm.sourceId, reference.path, reference.topic) }, modifier = Modifier.fillMaxWidth()) {
                    Text(stringResource(R.string.grammar_read_topic, reference.topic))
                }
            }

internal fun GrammarFocusSummary(focus: GrammarFocusDecision, activeSession: Boolean = false) {
    val current = focus.current ?: return
    var details by rememberSaveable(current.group.id, activeSession) { mutableStateOf(false) }
    Text(stringResource(
        if (activeSession || focus.continuing) R.string.grammar_focus_current else R.string.grammar_focus_next,
        current.group.label,
    ), style = MaterialTheme.typography.titleMedium)
    Text(stringResource(R.string.grammar_focus_guidance), style = MaterialTheme.typography.bodySmall)
    TextButton(onClick = { details = !details }) {
        Text(stringResource(if (details) R.string.grammar_focus_hide_details else R.string.grammar_focus_show_details))
    }
    if (!details) return
    if (activeSession) Text(stringResource(R.string.grammar_focus_snapshot), style = MaterialTheme.typography.bodySmall)
    Text(focus.reason, style = MaterialTheme.typography.bodySmall)
    GrammarRecommendationReadout(current)
    current.group.facets.forEach { facet ->
        val evidence = current.evidence.facets.getValue(facet.id)
        val introduced = focus.activation?.introduced.orEmpty().count { it.facetId == facet.id }
        Text(
            "${facet.label}: $introduced/2 new this activation; ${evidence.startedKeys} started contexts; " +
                "${evidence.positiveKeys} positive contexts, ${evidence.typedPositives} typed, ${evidence.spanMs / 3_600_000}h span.",
            style = MaterialTheme.typography.bodySmall,
        )
    }
    Text(
        when {
            !current.group.authored -> "Legacy contrast: no familiarity or prerequisite claim. Focus releases at its quota or exhaustion."
            current.evidence.familiar -> "Supported familiarity (not mastery)."
            else -> "Familiarity not yet supported."
        },
    )
    current.evidence.diagnostics.forEach { Text(it, style = MaterialTheme.typography.bodySmall) }
}

@Composable
fun GrammarPrompt(vm: GrammarQuizViewModel, exercise: GrammarExercise, answer: String? = null) {
    val rendered = GrammarVocabulary.render(exercise, answer)
    val color = MaterialTheme.colorScheme.primary
    val text = buildAnnotatedString {
        with(RareHan) { appendWithRare(rendered.text) }
        rendered.ranges.forEach { range ->
            val style = SpanStyle(
                color = color,
                textDecoration = TextDecoration.Underline,
                fontWeight = if (vm.isFamiliar(range.span)) FontWeight.Normal else FontWeight.SemiBold,
            )
            addLink(
                LinkAnnotation.Clickable("vocabulary:${range.start}", TextLinkStyles(style)) { vm.openLookup(range.span) },
                range.start, range.end,
            )
        }
    }
    Text(text, style = MaterialTheme.typography.headlineSmall,
        textAlign = TextAlign.Center, modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp))
    if (rendered.ranges.isNotEmpty()) {
        Text("Tap underlined words for help. Heavier links: not yet familiar in the app.",
            style = MaterialTheme.typography.bodySmall)
        OutlinedButton(onClick = vm::openVocabularyList, modifier = Modifier.fillMaxWidth()) { Text("Vocabulary") }
    }
    exercise.vocabularyProblem?.let { Text(it, style = MaterialTheme.typography.bodySmall) }
    Text(exercise.translation, style = MaterialTheme.typography.bodyMedium,
        modifier = Modifier.fillMaxWidth(), textAlign = TextAlign.Center)
}

@Serializable
enum class GrammarTargetKind { Group, Set, Chapter }

@Serializable
data class GrammarPracticeTarget(val sourceId: String, val branch: String, val kind: GrammarTargetKind, val id: String) {
    init {
        require(RepoSource.parse("https://github.com/$sourceId", branch)?.id == sourceId) { "Invalid practice source." }
        require(id.isNotBlank() && id.length <= 256 && id.none(Char::isISOControl)) { "Invalid practice target." }
    }

    target: GrammarPracticeTarget,
    sets: List<GrammarSet>,
    curriculum: GrammarCurriculumState,
    availability: Map<String, GrammarGroupAvailability>,
    contentVersion: String,
    parserEpoch: Int,
    scope: GrammarScope,
    limit: Int,
    readinessProblem: String? = null,
    notice: String? = null,
): GrammarPracticePreview {
    require(limit > 0) { "Practice batch size must be positive." }
    val groups = GrammarFocus.groups(sets).associateBy { it.id }
    val (label, ids) = when (target.kind) {
        GrammarTargetKind.Group -> {
            val group = requireNotNull(groups[target.id]) { "This learning group is no longer available. Choose a topic again." }
            group.label to group.members.map { it.exerciseId }
        }
        GrammarTargetKind.Set -> {
            val set = requireNotNull(sets.singleOrNull { it.id == target.id }) { "This Grammar set is no longer available. Choose a topic again." }
            set.title to set.exercises.map { it.id }
        }
        GrammarTargetKind.Chapter -> {
            require(curriculum is GrammarCurriculumState.Ready) {
                when (curriculum) {
                    GrammarCurriculumState.PendingRefresh -> "Sync needed before practising a chapter."
                    is GrammarCurriculumState.Invalid -> "Chapter practice unavailable: ${curriculum.reason}"
                    else -> "This source has no available chapter catalog. Choose a group or set."
                }
            }
            val chapter = requireNotNull(curriculum.curriculum.chapters.singleOrNull { it.id == target.id }) {
                "This chapter is no longer available. Choose a topic again."
            }
            chapter.label to chapter.groups.flatMap { id ->
                val group = requireNotNull(groups[id]?.takeIf { it.authored }) { "Chapter membership is invalid: $id." }
                group.members.map { it.exerciseId }
            }
        }
    }

        return GrammarPracticePreview(target, label, contentVersion, parserEpoch, scope, limit, members, labels, foundations, notice)
    }
}
